from pathlib import Path
import json
p=Path('draft_40be61cf_folder/review')
base='https://github.com/Harryleft/auto-civ6/blob/37c3593/docs/acceptance/'
def link(file,label):return f'<a href="{base}{file}">{label}</a>'
ops=[]
def add(start,content,end=None):ops.append({'start':start,'end':end,'content':content})
add('本局从原始基准', '<p>苏美尔在第 233 回合获得科技胜利，外交胜利点同时达到 19/20。支撑这场长任务的是三个环节：<b>给模型可信的事实，让模型判断行动价值，让执行环境确认动作结果。</b>本文用三个故障案例说明这些环节怎样配合。</p><p>本局包含用户战略指导、工具修复和检查点恢复，是一次持续迭代的工程实践。</p>', '这是一场边运行')
add('《文明 6》是一款','<p>《文明 6》是一款回合制策略游戏。玩家经营城市、发展科技与文化，指挥单位探索或作战，与其他文明交易、结盟。每回合先完成自己的选择，再交给其他玩家和游戏结算。下文的 <b>T195 表示第 195 回合</b>；「原生反馈」指游戏自身返回的状态。</p><p>本局主攻科技胜利：先研究出航天能力，再投入城市生产力完成航天项目，最终让远征飞船到达终点。外交胜利则需要累计 20 点，可通过世界议会投票、援助竞赛等方式获得。<b>研究得多不等于航天项目完成得早。</b></p>', '胜利有多条路线')
add('终局原生读取确认','<p>游戏自身确认了科技胜利；获胜前的 T232 存档和 T233 终局证据均已保留。'+link('2026-10-19-turn-terminal.md','终局与存档验收记录')+'</p>')
add('这里的 Harness','<p><b>Agent 决定做什么，Harness 保证操作有依据、结果可确认。</b>Harness 是模型与游戏之间的执行环境，包括查询与操作工具、结果确认、交互处理和存档恢复。下文的「未决」指动作已发出、结果尚未确认；「门禁」指此时阻止可能重复执行或依赖该结果的后续操作。</p>')
add('层次负责的判断','<table><thead><tr><th><p>信息与责任</p></th><th><p>本局如何使用</p></th></tr></thead><tbody><tr><td><p>稳定规则：机制是什么</p></td><td><p>按需查询文明、领袖能力和胜利条件；不必每回合重读全部知识。</p></td></tr><tr><td><p>动态事实：现在发生了什么</p></td><td><p>向游戏查询城市产出、可研究选项、对手航天进度与当前交互。</p></td></tr><tr><td><p>Agent 判断：现在值得做什么</p></td><td><p>选择科技主线、外交备用，比较行动与待命的机会成本。</p></td></tr><tr><td><p>Harness 执行：动作是否完成</p></td><td><p>核对本局和操作对象，只提交一次；结果不明就保留原请求，继续查证。</p></td></tr></tbody></table>')
add('图中蓝色部分','<p>蓝色表示模型判断，绿色表示执行与确认。结果不明时，先查原动作，避免把「没收到结果」当作「没有执行」。</p>')
add('行动能力不等于行动必要性','<p><b>能行动不等于需要行动。</b>T99 一名骑兵还有 4 点移动力，但生命值只有 53。选择留守治疗后，T100、T101 生命值升至 73、93。工具提供真实状态，Agent 根据战局决定是否移动。</p>')
add('知识入口也采用渐进式披露','<p>胜利路线同样需要看动态事实。终局时，本方研究了 69 项科技、拥有 2 座宇航中心，瑞典分别为 73 项和 4 座；本方飞船已到达终点，瑞典仍远未到达。本局把资源集中到关键航天项目及后续加速，而非追求所有总量指标领先。'+link('2026-10-19-turn-terminal.md','阶段决策证据')+' · <a href="https://github.com/Harryleft/auto-civ6/blob/37c3593/docs/architecture.md">执行环境架构</a> · '+link('2026-10-18-turn101-scheduling.md','待命验收')+'</p>')
add('决策输入：','<h1 seq="auto">案例一：工具说能研究，游戏却不允许（5 分钟）</h1>')
add('故障与修复','<h2 seq="auto">修复前：错误候选进入决策</h2><p>游戏里，科技研究解锁技术，市政研究解锁政策与治理能力。本局启用了随机研究树，解锁顺序可能与固定规则表不同。T195，工具仍按固定关系把部分市政列为可选，游戏实际上不允许研究。模型因此可能反复选择一个根本不能执行的目标。</p>', 'T195，静态市政')
add('修复后，查询入口','<h2 seq="auto">修复后：查询和提交都核对当前资格</h2><p>工具先向游戏确认当前可选项，提交前再核对一次。游戏未明确允许、查询异常或状态缺失时，不发出研究指令；目标已经选中时，只确认现状。规则知识解释研究的用途，游戏反馈决定此刻能否执行。</p><h2 seq="auto">实战证据：被禁用的选项不再出现</h2><p>T196，两个游戏不允许的市政已从候选中移除；允许的「全球化」仍可选择，重复选择也未再次执行。相关离线测试覆盖了资格缺失与重复选择边界。'+link('2026-10-19-native-civic-eligibility.md','资格修复验收')+'</p>', '外交作为备用路线')
add('异步外交：','<h1 seq="auto">案例二：愿意成交、真正成交和退出界面（6 分钟）</h1>')
add('旧流程为何会卡住','<h2 seq="auto">修复前：界面关闭，交易却没有结束</h2><p>外交交易不是一个立即完成的按钮：先提出条件，等对方评估，再决定成交或退出。旧工具发出请求后立即读取旧状态，可能把「对方愿意接受」误报为「已经成交」，或提前关窗。另一条路径只隐藏了界面，游戏仍停在外交交互中，导致无法正常结束回合。</p>', '交易评估和成交')
add('修复后，每次尝试','<h2 seq="auto">修复后：每个阶段单独确认</h2><p>每次报价只发一次，等待属于本局、本次交易的反馈。Agent 再决定试价、成交或退出；工具分别确认成交结果和外交会话是否真正结束。没有收到结果就继续核对原请求，不重复发起交易或结束回合。</p><h2 seq="auto">实战证据：瑞典和约经过试价后成交</h2><p>T138 至 T139，用户先协助了一次界面改价，随后工具补齐了编辑来约和评估能力。索要一次性 50、25、12 金币均遭拒绝；让游戏提出反报价后，得到和平、一件巨作及每回合 3 金币、持续 30 回合的可接受方案。Agent 明确接受后，工具确认条款生效、会话结束，游戏继续推进。</p><p>「巨作」是有文化价值的收藏品。报价评估与请求反报价是不同操作，同样条款也曾得到不同反馈；这次验证了有限试价和确认链路，没有证明获得了最高价格。'+link('2026-10-19-incoming-counteroffer.md','和约试价与成交验收')+'</p><h2 seq="auto">等待多久不是故障判断标准</h2><table><thead><tr><th><p>看到的状态</p></th><th><p>应对</p></th></tr></thead><tbody><tr><td><p>轮到其他电脑玩家，游戏仍能正常查询</p></td><td><p>继续等待结算。</p></td></tr><tr><td><p>仍轮到自己，外交或弹窗尚未结束</p></td><td><p>处理当前交互，再确认原来的结束回合请求。</p></td></tr><tr><td><p>连续无法查询游戏</p></td><td><p>诊断连接，必要时显式恢复。</p></td></tr></tbody></table><p>T78 的受控诊断中，不发起新交易约 5 秒即可推进；走旧交易路径后等待约 421 秒，期间查询未失联。它支持继续排查外交交互，但历史 T78 长等待的唯一原因仍未查明。'+link('2026-10-18-turn101-scheduling.md','等待诊断记录')+'</p>', 'T78 的受控诊断')
add('皇家学会：','<h1 seq="auto">案例三：一次项目贡献为何卡住整条任务链（6 分钟）</h1>')
add('不能把“暂时没变化”','<h2 seq="auto">修复前：读数没变就重发</h2><p>建造者是能修建农场等设施的单位，每个建造者只有有限的建设次数。拥有「皇家学会」建筑后，可以一次消耗建造者全部剩余次数，为所在城市的项目增加生产进度。本局用它加速航天项目。</p><p>旧工具发出贡献指令后立即检查剩余次数；读数暂未更新，就可能重发或改走直接执行。第一次是否成功尚未确认，第二次操作又进来了，单位消耗和项目进度就可能失去对应关系。</p>', '皇家学会允许建造者')
add('修复将一次贡献','<h2 seq="auto">修复后：只发一次，用两项事实共同确认</h2><p>工具记录本局、建造者和目标项目，先开始监听反馈，再提交一次贡献。只有同时确认<b>建造者已消耗、对应项目有进展或已完成</b>，才报告成功。事件迟到或顺序颠倒时，保留原请求继续查证。</p><p><b>T191：</b>建造者的 6 次建设次数被消耗，月球项目进度从 374 增至 530；再操作旧单位时，工具确认它已不存在，没有重发贡献。恢复存档后，单位消耗和项目进度仍保持一致。'+link('2026-10-19-royal-society-contribution.md','贡献确认验收')+'</p><h2 seq="auto">进一步暴露的问题：防重复保护挡住了解锁</h2><p><b>T231：</b>贡献已提交，项目完成弹窗却暂停了游戏处理；工具的防重复门禁又因贡献未确认而禁止关窗，形成循环：<b>贡献等游戏继续，游戏等弹窗关闭，关闭操作又等贡献确认。</b></p><p>现场通过标准界面关闭弹窗后，原贡献立即确认，项目进度从 0 增至 110，没有重发贡献或重载。修复只放开「显式关闭弹窗」这个入口：关窗解除暂停，原贡献仍需继续确认，其他依赖它的操作仍受保护。</p><p>新增工具在 T232 实机通过了关窗验证；完整的「贡献未决时关窗，再确认原贡献」链路由离线回归测试覆盖。'+link('2026-10-19-contribution-popup-progress.md','弹窗与未决保护验收')+'</p><h2 seq="auto">恢复也要核对结果</h2><p>需要恢复时，优先返回主菜单加载已确认的检查点；若仍有无法确认的动作，保留保护门禁，显式选择完整故障恢复。T232 菜单恢复约 30 秒完成，城市、单位和航天进度一致；总分展示存在差异，原始记录予以保留。随后推进到 T233，游戏确认科技胜利。</p>', 'T232 结果存档通过菜单恢复')
add('本局能持续推进','<p>检查长任务 Agent 时，可以直接核对以下六项。它们约束事实与操作，不替模型预设每个回合的策略。</p>')
add('契约验收问题','<table><thead><tr><th><p>要保证什么</p></th><th><p>如何检查</p></th></tr></thead><tbody><tr><td><p>输入可信</p></td><td><p>规则说明与游戏当前资格是否分开？</p></td></tr><tr><td><p>模型能作取舍</p></td><td><p>是否允许待命、保留资源或调整胜利路线？</p></td></tr><tr><td><p>反馈属于本次操作</p></td><td><p>是否核对本局、操作对象与当前尝试？</p></td></tr><tr><td><p>未知不会引发重复执行</p></td><td><p>结果迟到或缺失时，是否保留原请求并阻止依赖操作？</p></td></tr><tr><td><p>保护机制能够解除真正阻塞</p></td><td><p>能否结束当前交互，同时继续确认原动作？</p></td></tr><tr><td><p>恢复有证据</p></td><td><p>加载后是否核对城市、单位和关键胜利进度？</p></td></tr></tbody></table>')
add('验证分三层','<p><b>验证分三层：</b>离线模拟迟到、乱序、重复和错误身份等边界，只运行受影响模块；实机检查真实反馈与交互解除；恢复和终局验收核对关键状态及胜负。测试数量不等于完整覆盖，胜利也不能替代边界测试。</p><p>终局后审查仍发现两处交易边界问题，修复后完成了相关离线验证，未追加实机测试。'+link('2026-10-19-incoming-p2-boundaries.md','终局后回归记录')+'</p><p>经验记录保留四项即可：<b>看到了什么—据此怎样判断—执行了什么—游戏实际发生了什么。</b>例如，本局有关键航天进度支持「项目转化比科技总量更影响胜负」的判断；对手内部为何晚做项目，证据不足，仍需继续验证。</p>', '后续积累应记录')
(p/'patch-plan.json').write_text(json.dumps(ops,ensure_ascii=False,indent=2))
print(len(ops),'patches prepared')
